class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        word = [None] * L
        fixed = [False] * L
        for i, c in enumerate(str1):
            if c == 'T':
                for k in range(m):
                    p = i + k
                    if fixed[p]:
                        if word[p] != str2[k]:
                            return ""
                    else:
                        fixed[p] = True
                        word[p] = str2[k]
        for p in range(L):
            if not fixed[p]:
                word[p] = 'a'
        for i, c in enumerate(str1):
            if c == 'F':
                if word[i:i + m] == list(str2):
                    # find rightmost free position in window
                    chosen = -1
                    for p in range(i + m - 1, i - 1, -1):
                        if not fixed[p]:
                            chosen = p
                            break
                    if chosen == -1:
                        return ""
                    word[chosen] = 'b'
        # verify
        s = "".join(word)
        for i, c in enumerate(str1):
            sub = s[i:i + m]
            if c == 'T' and sub != str2:
                return ""
            if c == 'F' and sub == str2:
                return ""
        return s
